<template>
 <div class="app-container official">
  <div class="heading"><div><h2>官方模板</h2><p>维护可复用的工作流。发布固定版本，创作者复制后独立编辑。</p></div><el-button v-if="has('podAdmin:template:edit')" type="primary" :disabled="!!pending" @click="open('official.create')">新建模板</el-button></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <el-alert v-if="pending" title="上一项操作待核对，请先确认原结果" type="warning" :closable="false"><p>{{ pending.requestId }}。工作流正文、文件和原因不存入浏览器草稿，重试需重填原内容。</p><el-button :loading="saving" @click="checkPending">核对原操作</el-button><el-button :disabled="saving" @click="recover">重填原操作</el-button></el-alert>
  <el-tabs v-model="tab" @tab-change="search"><el-tab-pane label="工作流模板" name="templates"/><el-tab-pane v-if="has('podAdmin:template:edit')" label="平台素材" name="assets"/></el-tabs>
  <el-form inline @submit.prevent="search"><el-form-item v-if="tab==='templates'" label="名称"><el-input v-model="name" clearable/></el-form-item><el-form-item><el-button :loading="loading" @click="search">刷新列表</el-button><el-button v-if="tab==='assets'" :disabled="!!pending" @click="openUpload">上传平台图片</el-button></el-form-item></el-form>
  <el-table v-loading="loading" :data="rows" :empty-text="tab==='templates'?'还没有官方模板，可先从起始流程新建草稿':'还没有平台图片，上传时请填写使用权说明'">
   <template v-if="tab==='templates'"><el-table-column label="模板" min-width="200"><template #default="{row}"><strong>{{ row.name }}</strong><div class="muted">{{ row.code }} · #{{ row.templateId }}</div></template></el-table-column><el-table-column prop="description" label="说明" min-width="180" show-overflow-tooltip/><el-table-column label="发布状态" min-width="130"><template #default="{row}"><el-tag :type="row.status==='published'?'success':'info'">{{ statuses[row.status] }}</el-tag><div class="muted">{{ row.publishedVersionId ? `发布版本 ID ${row.publishedVersionId}` : '尚未发布' }}</div></template></el-table-column><el-table-column prop="sort" label="排序" width="80"/><el-table-column label="操作" min-width="350"><template #default="{row}"><el-button v-if="has('podAdmin:template:query')" link type="primary" @click="show(row)">版本与发布</el-button><el-button v-if="has('podAdmin:template:edit')" link :disabled="!!pending" @click="open('official.update',row)">编辑说明</el-button><el-button v-if="has('podAdmin:template:edit')" link :disabled="!!pending" @click="editVersion(row)">新增版本</el-button><el-button v-if="has('podAdmin:template:publish')&&row.status==='published'" link type="danger" :disabled="!!pending" @click="open('official.unpublish',row)">下架</el-button></template></el-table-column></template>
   <template v-else><el-table-column prop="assetId" label="素材 ID" width="100"/><el-table-column prop="name" label="文件名" min-width="180"/><el-table-column label="尺寸" min-width="120"><template #default="{row}">{{ row.width }} × {{ row.height }}</template></el-table-column><el-table-column prop="licenseNote" label="使用权说明" min-width="220" show-overflow-tooltip/><el-table-column prop="createTime" label="上传时间" min-width="165"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link @click="preview(row)">预览</el-button></template></el-table-column></template>
  </el-table><pagination v-show="total>0" v-model:page="page" v-model:limit="size" :total="total" @pagination="load"/>
  <el-dialog v-model="dialog" :title="titles[op]" width="880px" :close-on-click-modal="false"><el-form label-width="105px" @submit.prevent>
   <el-form-item v-if="op==='official.create'" label="模板编码" required><el-input v-model="form.code" maxlength="64" placeholder="英文小写，如 floral-print"/></el-form-item>
   <template v-if="['official.create','official.update'].includes(op)"><el-form-item label="名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" maxlength="500"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0" :max="100000" :precision="0"/></el-form-item></template>
   <GraphEditor v-if="['official.create','official.version'].includes(op)" v-model="form.graph" :assets="assetOptions" :asset-total="assetTotal" :assets-loading="assetsLoading" @load-assets="loadAssetOptions(true)"/>
   <p v-if="['official.create','official.version'].includes(op)" class="muted">素材仅能使用平台素材 ID；没有默认图可留空。保存不执行模型，也不会改变已经发布的版本。</p>
   <el-alert v-if="op==='official.publish'" :title="`将版本 ID ${form.versionId} 设为当前发布版本。已复制到用户空间的项目不会变化。`" type="info" :closable="false"/>
   <el-alert v-if="op==='official.unpublish'" title="下架后不再允许新复制，已有用户副本与已接受的复制计划继续保留。" type="warning" :closable="false"/>
   <el-form-item label="操作原因" required><el-input v-model="form.reason" maxlength="200"/></el-form-item>
  </el-form><template #footer><el-button :disabled="saving" @click="dialog=false">关闭</el-button><el-button type="primary" :loading="saving" @click="submit">确认保存</el-button></template></el-dialog>
  <el-dialog v-model="versionsOpen" :title="`${selected?.name || ''} · 历史版本`" width="820px"><el-alert v-if="versionError" :title="versionError" type="error" :closable="false"/><el-table :data="versions" v-loading="versionsLoading"><el-table-column prop="version" label="版本" width="80"/><el-table-column prop="versionId" label="版本 ID" width="100"/><el-table-column prop="createTime" label="保存时间" min-width="170"/><el-table-column prop="publishedAt" label="首次发布" min-width="170"/><el-table-column label="操作" min-width="150"><template #default="{row}"><el-button v-if="has('podAdmin:template:publish')" link type="primary" :disabled="!!pending" @click="open('official.publish',selected,row.versionId)">发布此版本</el-button></template></el-table-column></el-table><pagination v-show="versionTotal>0" v-model:page="versionPage" v-model:limit="versionSize" :total="versionTotal" @pagination="loadVersions"/></el-dialog>
  <el-dialog v-model="uploadOpen" title="上传平台图片" width="580px" :close-on-click-modal="false"><el-alert title="请仅上传有权向创作者提供的图片；不会引用用户的私人素材。" type="info" :closable="false"/><el-form label-width="100px"><el-form-item label="使用权说明" required><el-input v-model="license" type="textarea" maxlength="500" placeholder="如：本人原创，允许平台用户用于商品设计"/></el-form-item><el-form-item label="图片" required><input type="file" accept="image/png,image/jpeg,image/webp" @change="chooseFile"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="uploadOpen=false">关闭</el-button><el-button type="primary" :loading="saving" @click="upload">确认上传</el-button></template></el-dialog>
  <el-dialog v-model="previewOpen" title="平台图片" width="680px" @closed="clearPreview"><img v-if="previewURL" :src="previewURL" alt="平台素材预览" style="max-width:100%;max-height:65vh;object-fit:contain"/></el-dialog>
 </div>
</template>
<script setup>
import { createUUID } from '@/utils/uuid'
import{onMounted,onBeforeUnmount,reactive,ref}from'vue'
import{ElMessage}from'element-plus'
import useUserStore from'@/store/modules/user'
import{adminList,adminGet,adminFile,catalogWrite,catalogAction,officialUpload}from'@/api/pod/admin'
import GraphEditor from'./GraphEditor.vue'
const user=useUserStore(),has=p=>user.podAdmin?.permissions?.includes(p),tab=ref('templates'),name=ref(''),rows=ref([]),total=ref(0),page=ref(1),size=ref(10),loading=ref(false),error=ref(''),saving=ref(false),dialog=ref(false),op=ref(''),form=reactive({}),assetOptions=ref([]),pending=ref(null)
const statuses={draft:'草稿',published:'已发布',unpublished:'已下架'},titles={'official.create':'新建官方模板','official.update':'编辑模板说明','official.version':'保存新版本','official.publish':'发布指定版本','official.unpublish':'下架模板'},pendingKey=`pod-admin.official:${user.id}`;let sequence=0,versionSequence=0,previewSequence=0
function savePending(){if(pending.value)sessionStorage.setItem(pendingKey,JSON.stringify(pending.value));else sessionStorage.removeItem(pendingKey)}
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const r=await adminList(`catalog/${tab.value}`,{name:name.value,pageNum:page.value,pageSize:size.value});if(seq===sequence){rows.value=r.rows;total.value=r.total}}catch(e){if(seq===sequence)error.value=e.message}finally{if(seq===sequence)loading.value=false}}
function search(){page.value=1;load()}
const assetTotal=ref(0),assetPage=ref(1),assetsLoading=ref(false)
async function loadAssetOptions(more=false){if(!has('podAdmin:template:edit')||assetsLoading.value)return;assetsLoading.value=true;try{const next=more?assetPage.value+1:1,r=await adminList('catalog/assets',{pageNum:next,pageSize:100});assetOptions.value=more?[...new Map([...assetOptions.value,...r.rows].map(a=>[a.assetId,a])).values()]:r.rows;assetPage.value=next;assetTotal.value=r.total}finally{assetsLoading.value=false}}
function open(value,row={},versionId=''){op.value=value;Object.assign(form,{id:row.templateId||'',revision:row.revision||'',code:'',name:row.name||'',description:row.description||'',sort:row.sort||0,graph:null,versionId,reason:''});dialog.value=true}
async function editVersion(row){error.value='';try{const r=await adminGet(`catalog/templates/${row.templateId}`);await loadAssetOptions();open('official.version',r.data.template);form.graph=r.data.snapshot?.graph||null}catch(e){error.value=e.message}}
async function submit(){if(saving.value)return;if(pending.value&&pending.value.op!==op.value){error.value='请先核对原操作';return;}saving.value=true;error.value='';try{if(!form.reason?.trim())throw new Error('请填写操作原因');let data={reason:form.reason},method='POST',path='catalog/templates';if(op.value==='official.create')Object.assign(data,{code:form.code,name:form.name,description:form.description,sort:form.sort,graph:form.graph});else{data.revision=form.revision;path+=`/${form.id}`;if(op.value==='official.update'){method='PUT';Object.assign(data,{name:form.name,description:form.description,sort:form.sort})}else if(op.value==='official.version'){path+='/versions';data.graph=form.graph}else if(op.value==='official.publish'){path+='/publish';data.versionId=form.versionId}else path+='/unpublish'}
 if(!pending.value){pending.value={op:op.value,id:form.id,revision:form.revision,versionId:form.versionId,requestId:createUUID()};savePending()};await catalogWrite(method,path,{...data,requestId:pending.value.requestId});pending.value=null;savePending();dialog.value=false;versionsOpen.value=false;ElMessage.success('已保存');load()}catch(e){error.value=e.message;if([400,403,404].includes(e.code)){pending.value=null;savePending()}}finally{saving.value=false}}
async function checkPending(){saving.value=true;try{await catalogAction(pending.value.requestId);pending.value=null;savePending();ElMessage.success('原操作已完成');load()}catch(e){error.value=e.message}finally{saving.value=false}}
function recover(){if(pending.value.op==='official.asset'){uploadOpen.value=true;license.value='';uploadFile.value=null;return}open(pending.value.op,{templateId:pending.value.id,revision:pending.value.revision},pending.value.versionId)}
const versionsOpen=ref(false),versionsLoading=ref(false),versions=ref([]),versionTotal=ref(0),versionPage=ref(1),versionSize=ref(10),versionError=ref(''),selected=ref(null)
async function show(row){selected.value=row;versionsOpen.value=true;versionPage.value=1;await loadVersions()}
async function loadVersions(){const seq=++versionSequence;versionsLoading.value=true;versionError.value='';try{const r=await adminList(`catalog/templates/${selected.value.templateId}/versions`,{pageNum:versionPage.value,pageSize:versionSize.value});if(seq===versionSequence){versions.value=r.rows;versionTotal.value=r.total}}catch(e){if(seq===versionSequence)versionError.value=e.message}finally{if(seq===versionSequence)versionsLoading.value=false}}
const uploadOpen=ref(false),uploadFile=ref(null),license=ref('');function openUpload(){license.value='';uploadFile.value=null;uploadOpen.value=true}function chooseFile(e){uploadFile.value=e.target.files?.[0]||null}
async function upload(){if(saving.value)return;if(pending.value&&pending.value.op!=='official.asset'){error.value='请先核对原操作';return;}saving.value=true;error.value='';try{if(!uploadFile.value||!license.value.trim())throw new Error('请选择图片并填写使用权说明');if(!pending.value){pending.value={op:'official.asset',requestId:createUUID()};savePending()};await officialUpload(pending.value.requestId,license.value,uploadFile.value);pending.value=null;savePending();uploadOpen.value=false;uploadFile.value=null;ElMessage.success('图片已上传');load();await loadAssetOptions()}catch(e){error.value=e.message;if([400,403,404].includes(e.code)){pending.value=null;savePending()}}finally{saving.value=false}}
const previewOpen=ref(false),previewURL=ref('');function clearPreview(){++previewSequence;if(previewURL.value)URL.revokeObjectURL(previewURL.value);previewURL.value=''}async function preview(row){clearPreview();const seq=previewSequence;previewOpen.value=true;try{const blob=await adminFile(`catalog/assets/${row.assetId}/content`);if(seq===previewSequence&&previewOpen.value)previewURL.value=URL.createObjectURL(blob)}catch(e){error.value=e.message}}
onMounted(()=>{try{const raw=sessionStorage.getItem(pendingKey);if(raw){const p=JSON.parse(raw);if(/^official\.(create|update|version|publish|unpublish|asset)$/.test(p.op)&&/^[0-9a-f-]{36}$/.test(p.requestId))pending.value=p;else error.value='待核对记录无效'}}catch{error.value='无法读取待核对记录'};load();loadAssetOptions().catch(e=>error.value=e.message)})
onBeforeUnmount(()=>{++sequence;++versionSequence;clearPreview()})
</script>
<style scoped>.heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.heading h2{margin:0 0 8px}.heading p,.muted{color:var(--el-text-color-secondary)}.muted{font-size:12px;margin-top:4px}.official :deep(.el-alert){margin:12px 0}.official :deep(.el-form-item){margin-bottom:14px}@media(max-width:700px){.heading{align-items:flex-start;flex-direction:column}}</style>
